package ama.transcript;
import ama.task.*;import javax.sql.DataSource;import java.sql.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Synthetic JDBC pages through the REAL maintenance loop. No authentic row, recovery, clock or runtime qualification. */
class Task11B3MaintenanceCursorComponentTest {
 static final String BASE="SELECT s.task_id,s.publication_id,CAST(s.created_at AS CHAR) created_at,t.state,m.id meeting_id,m.owner_id,m.revision,p.revision publication_revision,i.status FROM publication_submission s JOIN durable_task t ON t.id=s.task_id JOIN publication p ON p.id=s.publication_id JOIN meeting m ON m.id=p.meeting_id JOIN enterprise_identity i ON i.enterprise_id=m.owner_id WHERE s.local_state='UNDECIDED'";
 static final String CURSOR=" AND (s.created_at>? OR (s.created_at=? AND s.task_id>?))",ORDER=" ORDER BY s.created_at,s.task_id LIMIT 64",TIME="2026-10-26 00:00:00.000000";
 static final List<String> COLUMNS=List.of("task_id","publication_id","created_at","state","meeting_id","owner_id","revision","publication_revision","status");
 record Page(List<Object> args,List<Map<String,Object>> rows){}
 static List<Map<String,Object>> rows(int first,int count,String state,String status){var rows=new ArrayList<Map<String,Object>>();for(int n=first;n<first+count;n++){var row=new LinkedHashMap<String,Object>();row.put("task_id",String.format("synthetic-%03d",n));row.put("publication_id","invalid-no-authority");row.put("created_at",TIME);row.put("state",state);row.put("meeting_id","invalid-no-authority");row.put("owner_id","synthetic-owner");row.put("revision",1L);row.put("publication_revision",1L);row.put("status",status);rows.add(row);}return rows;}
 static List<Object> after(int row){return List.of(TIME,TIME,String.format("synthetic-%03d",row));}
 static final class Fixture {
  final DataSource ds=mock(DataSource.class);final JdbcTranscriptAuthority authority=mock(JdbcTranscriptAuthority.class);final Queue<Page> pages=new ArrayDeque<>();final List<String> sql=new ArrayList<>();final AtomicInteger reads=new AtomicInteger();final JdbcPublicationLocalRecovery local;
  Fixture()throws Exception {
   when(authority.dataSource()).thenReturn(ds);when(authority.publicationDomain()).thenReturn(mock(PublicationTaskDomainPolicy.class));
   when(ds.getConnection()).thenAnswer(inv->{var connection=mock(Connection.class);when(connection.prepareStatement(anyString())).thenAnswer(call->{String text=call.getArgument(0);assertTrue(text.equals(BASE+ORDER)||text.equals(BASE+CURSOR+ORDER),"Only the exact bounded scan SELECT may reach fake JDBC");assertFalse(pages.isEmpty(),"Unexpected extra scan");Page page=pages.remove();assertEquals(page.args.isEmpty()?BASE+ORDER:BASE+CURSOR+ORDER,text);sql.add(text);var params=new TreeMap<Integer,Object>();var statement=mock(PreparedStatement.class);doAnswer(set->{params.put(set.getArgument(0),set.getArgument(1));return null;}).when(statement).setString(anyInt(),anyString());doAnswer(set->{params.put(set.getArgument(0),set.getArgument(1));return null;}).when(statement).setObject(anyInt(),any());when(statement.executeQuery()).thenAnswer(query->{assertEquals(page.args,new ArrayList<>(params.values()));reads.incrementAndGet();var rs=mock(ResultSet.class);var metadata=mock(ResultSetMetaData.class);when(metadata.getColumnCount()).thenReturn(COLUMNS.size());when(metadata.getColumnLabel(anyInt())).thenAnswer(column->COLUMNS.get((Integer)column.getArgument(0)-1));when(rs.getMetaData()).thenReturn(metadata);var at=new AtomicInteger(-1);when(rs.next()).thenAnswer(next->at.incrementAndGet()<page.rows.size());when(rs.getObject(anyInt())).thenAnswer(column->page.rows.get(at.get()).get(COLUMNS.get((Integer)column.getArgument(0)-1)));return rs;});when(statement.executeUpdate()).thenThrow(new AssertionError("No synthetic business writes"));when(statement.execute()).thenThrow(new AssertionError("No synthetic business execution"));return statement;});when(connection.createStatement()).thenThrow(new AssertionError("No literal SQL"));when(connection.prepareCall(anyString())).thenThrow(new AssertionError("No callable SQL"));doThrow(new AssertionError("No transaction")).when(connection).setAutoCommit(false);doThrow(new AssertionError("No commit")).when(connection).commit();return connection;});
   local=new JdbcPublicationLocalRecovery(authority,mock(TranscriptAcquisitionBudget.class),mock(JdbcTaskQueue.class),mock(JdbcOutbox.class));
  }
  void page(List<Object> args,List<Map<String,Object>> rows){assertTrue(rows.size()<=64);pages.add(new Page(args,rows));}
  void nextCadence()throws Exception {var field=JdbcPublicationLocalRecovery.class.getDeclaredField("maintenanceNextNanos");field.setAccessible(true);field.setLong(local,0);}
  void noAuthority(){verify(authority,never()).transactionRunner();assertTrue(pages.isEmpty());}
 }
 @Test void actual64RowPageAndPersistentKeysetReachLaterCandidateWithoutSkippingIt()throws Exception {
  var f=new Fixture();f.page(List.of(),rows(1,64,"READY","ACTIVE"));var first=f.local.maintainLocalFailures();assertEquals(64,first.scanned());assertEquals(0,first.attempted());assertEquals(0,first.recovered());assertFalse(first.endOfPass());var throttled=f.local.maintainLocalFailures();assertEquals(0,throttled.scanned());assertEquals(1,f.reads.get());
  f.nextCadence();f.page(after(64),rows(65,1,"FAILED","ACTIVE"));var later=f.local.maintainLocalFailures();assertEquals(1,later.scanned());assertEquals(1,later.attempted());assertEquals(0,later.recovered());assertTrue(later.endOfPass());f.nextCadence();f.page(List.of(),List.of());assertTrue(f.local.maintainLocalFailures().endOfPass());assertEquals(3,f.reads.get());f.noAuthority();
 }
 @Test void attempt16BoundaryAdvancesOnlyThroughActuallyProcessedRows()throws Exception {
  var f=new Fixture();for(int pass=0;pass<4;pass++){if(pass>0)f.nextCadence();f.page(pass==0?List.of():after(pass*16),rows(pass*16+1,64-pass*16,"FAILED","ACTIVE"));var result=f.local.maintainLocalFailures();assertEquals(16,result.scanned());assertEquals(16,result.attempted());assertEquals(0,result.recovered());assertEquals(pass==3,result.endOfPass());}assertEquals(4,f.reads.get());f.noAuthority();
 }
 @Test void activeTerminalEligibilityDoesNotInventRecoveryAuthority()throws Exception {
  var f=new Fixture();var rows=new ArrayList<Map<String,Object>>();String[] states={"READY","RUNNING","RECONCILING","UNKNOWN","FAILED","CANCELLED","STALE","FAILED"};for(int n=0;n<states.length;n++)rows.addAll(rows(n+1,1,states[n],n==4?"DISABLED":"ACTIVE"));f.page(List.of(),rows);var result=f.local.maintainLocalFailures();assertEquals(8,result.scanned());assertEquals(3,result.attempted());assertEquals(0,result.recovered());assertTrue(result.endOfPass());f.noAuthority();
 }
 @Test void newInstanceStartsItsOwnCursorAndNeverAcquiresOldAuthority()throws Exception {
  var first=new Fixture();first.page(List.of(),rows(1,64,"READY","ACTIVE"));assertFalse(first.local.maintainLocalFailures().endOfPass());var restarted=new Fixture();restarted.page(List.of(),List.of());assertTrue(restarted.local.maintainLocalFailures().endOfPass());first.noAuthority();restarted.noAuthority();
 }
}